async function attach(file){if(!file||!Number.isFinite(file.size)||file.size<=0||file.size>20000000)throw Error('Use um arquivo de até 20 MB.');let pdf=/\.pdf$/i.test(file.name)&&['','application/pdf','application/octet-stream'].includes(file.type||''),image=/^image\/(jpeg|png|webp|gif|heic|heif)$/.test(file.type||'');if(!pdf&&!image)throw Error('Anexe PDF ou imagem (JPEG, PNG ou foto compatível).');let stored=await root.LocalFiles.prepare(file);if(pdf){stored.type='application/pdf';stored.dataURL=stored.dataURL.replace(/^data:[^;]+;/,'data:application/pdf;')}let meta={id:stored.id,name:stored.name,type:stored.type};validateAttachments([meta]);await root.LocalFiles.put([stored]);return meta}
