function bindAttachments(){for(let el of document.querySelectorAll('[data-labor-file-open]'))el.onclick=async()=>{let tab;try{let [i,j]=el.dataset.laborFileOpen.split(':').map(Number),meta=draft.measurements[i].attachments[j];tab=root.open?.('about:blank','_blank');if(tab)tab.opener=null;let file=(await root.LocalFiles.load([meta.id]))[0],text=file.dataURL.split(',')[1],data=root.atob(text),bytes=new Uint8Array(data.length);for(let k=0;k<data.length;k++)bytes[k]=data.charCodeAt(k);let url=root.URL.createObjectURL(new Blob([bytes],{type:meta.type}));if(tab)tab.location.href=url;else{let a=document.createElement('a');a.href=url;a.download=meta.name;a.click()}root.setTimeout(()=>root.URL.revokeObjectURL(url),60000)}catch(e){tab?.close();api.toast(e.message)}};if(readOnly)return;for(let el of document.querySelectorAll('[data-labor-file-remove]'))el.onclick=()=>{if(pending)return;let [i,j]=el.dataset.laborFileRemove.split(':').map(Number);draft.measurements[i].attachments.splice(j,1);draw()};for(let el of document.querySelectorAll('[data-labor-file]'))el.onchange=async e=>{if(pending)return;let row=draft.measurements[Number(el.dataset.laborFile)],files=Array.from(e.target.files||[]);if(!files.length)return;pending=true;for(let field of document.querySelectorAll('.labor-editor input,.labor-editor select,.labor-editor button'))field.disabled=true;try{let metas=[];for(let file of files)metas.push(await attach(file));row.attachments=[...(row.attachments||[]),...metas];pending=false;draw();api.toast('Comprovantes anexados. Salve o contrato para confirmar a medição e sincronizar os arquivos.')}catch(err){pending=false;draw();$('#laborError').textContent=err.message}}}
