function render(s,p){let rows=(s.laborContracts||[]).filter(c=>p==='all'||c.project===p);return '<section class="panel"><div class="panel-head"><h2>Contratos de mão de obra</h2><button class="button primary" data-action="labor-new">+ Contrato de mão de obra</button></div><div class="notice neutral">Registre o valor total contratado. Só as medições marcadas como Liberada geram parcelas em Contas a Pagar. Exemplo: contrato de R$ 100 mil, medição liberada de R$ 15 mil: a pagar R$ 15 mil; saldo a liberar R$ 85 mil. O contrato total permanece comprometido no orçamento, sem duplicar suas parcelas.</div><div class="table-wrap"><table><thead><tr><th>Contrato / obra</th><th>Prestador</th><th>Total contratado</th><th>Liberado em medições</th><th>Pago</th><th>Saldo a liberar</th><th></th></tr></thead><tbody>'+rows.map(c=>{let paid=D.sum(s.costs.filter(x=>x.laborContract===c.id),x=>x.paid);return '<tr><td>'+h(c.number||c.description)+'<br>'+h(s.projects.find(p=>p.id===c.project)?.name)+'<br><small>'+h(c.scope==='Obra geral'?'Obra geral':D.financialStages(s).find(st=>st.id===c.stage)?.name||'Etapa')+'</small></td><td>'+h(c.supplier)+'</td><td>'+money(c.amount)+'</td><td>'+money(released(c))+'</td><td>'+money(paid)+'</td><td>'+money((cents(c.amount)-cents(released(c)))/100)+'</td><td><button class="text-btn" data-action="labor-view:'+h(c.id)+'">Visualizar</button><button class="text-btn" data-action="labor-edit:'+h(c.id)+'">Editar / medições</button><button class="text-btn red-text" data-action="labor-remove:'+h(c.id)+'">Excluir</button></td></tr>'}).join('')+'</tbody></table></div>'+(rows.length?'':'<div class="empty">Cadastre um contrato de mão de obra para começar.</div>')+'</section>'}
